/* Game day claim - runs inside englandicehockey.adhoc.expensein.com */
(function(){
  if(!/expensein\.com$/.test(location.hostname)){ alert("Open ExpenseIn and sign in first, then tap Game day claim again."); return; }
  const old = document.getElementById("gdc");
  if(old){ old.hidden = false; return; }

  const FORM_B64 = window.__GDC_FORM || "";
  const TEST = !!window.__GDC_TEST;
  const HAS_FORM = FORM_B64.length>1000;
  const RATE = 0.45;
  const RINKS = [
    {key:"Basingstoke", venue:"Planet Ice Basingstoke", pc:"RG22 6PG"},
    {key:"Bristol", venue:"Planet Ice Bristol", pc:"BS10 7SR"},
    {key:"Hull", venue:"Hull Arena", pc:"HU1 2DZ"},
    {key:"Leeds", venue:"Planet Ice Leeds", pc:"LS11 0EY"},
    {key:"Milton Keynes", venue:"Planet Ice Milton Keynes", pc:"MK9 1BL"},
    {key:"Peterborough", venue:"Planet Ice Peterborough", pc:"PE3 8YN"},
    {key:"Romford", venue:"Sapphire Ice & Leisure", pc:"RM7 0AE"},
    {key:"Sheffield", venue:"iceSheffield", pc:"S9 5DA"},
    {key:"Solway", venue:"Dumfries Ice Bowl", pc:"DG2 9AN"},
    {key:"Swindon", venue:"Link Centre", pc:"SN5 7DL"},
    {key:"Telford", venue:"Telford Ice Rink", pc:"TF3 4JQ"}
  ];
  const EXTRA = {park:{label:"Parking",merchant:"Parking"}, toll:{label:"Toll or charge",merchant:"Toll"}, ferry:{label:"Ferry or flight",merchant:"Ferry"}};
  const VAT = ["Zero Rated (0%)","Reduced Rate (5%)","Standard Rate (20%)"];
  const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

  const store = {
    get(k,d){ try{ const v=localStorage.getItem("gdc:"+k); return v?JSON.parse(v):d; }catch(e){ return d; } },
    set(k,v){ try{ localStorage.setItem("gdc:"+k,JSON.stringify(v)); }catch(e){} }
  };
  const num = v => { const n=parseFloat(v); return isFinite(n)?n:0; };
  const money = n => (Math.round(num(n)*100)/100).toFixed(2);
  const esc = s => String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

  let profile = store.get("profile",{first:"",last:"",town:"",homePc:"",fee:"",comp:"NIHL National",sig:""});
  let pcs = store.get("pc",{});
  let game = blank();
  const files = {}; // extra index -> File (receipt photos, kept in memory only)
  function feeFor(pos){ return pos==="linesman" ? "50" : (profile.fee && num(profile.fee)>0 ? String(num(profile.fee)) : "75"); }
  function blank(){ return {date:"",arrive:"",rink:"",rinkPc:"",home:"",away:"",comp:profile.comp||"NIHL National",position:"referee",fee:feeFor("referee"),miles:"",milesAuto:false,split:false,claimed:"",mileNotes:"",shared:false,meetPc:"",role:"passenger",pax:"1",soloMiles:"",sharedMiles:"",extras:[]}; }

  /* ---------- styles ---------- */
  if(!document.getElementById("gdc-fonts")){
    const l=document.createElement("link"); l.id="gdc-fonts"; l.rel="stylesheet";
    l.href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;700&family=Barlow:wght@400;500;600&display=swap";
    document.head.appendChild(l);
  }
  const css = `
  #gdc{--ice:#EEF4F8;--surface:#fff;--board:#162A45;--ink:#1B2B40;--muted:#5B6B80;--blue:#2257C9;--red:#C8102E;--crease:#D6E5F3;--line:#C9D6E3;--ok:#1E7A4F;
    position:fixed;inset:0;z-index:2147483000;background:var(--ice);color:var(--ink);overflow-y:auto;-webkit-overflow-scrolling:touch;
    font:16px/1.5 Barlow,system-ui,-apple-system,"Segoe UI",sans-serif;padding-bottom:env(safe-area-inset-bottom,0px)}
  @media (prefers-color-scheme:dark){#gdc{--ice:#0F1B2B;--surface:#172638;--board:#0A1422;--ink:#E6EEF6;--muted:#9AAAC0;--blue:#6E9BFF;--red:#FF5A6E;--crease:#1F3550;--line:#2A405C;--ok:#4CC38A}}
  #gdc *,#gdc *::before,#gdc *::after{box-sizing:border-box}
  #gdc .wrap{max-width:560px;margin:0 auto;padding:0 14px 40px}
  #gdc h2,#gdc h3,#gdc .cond{font-family:"Barlow Condensed","Arial Narrow",sans-serif;margin:0}
  #gdc .board{background:var(--board);color:#fff;margin:0 -14px 16px;padding:calc(14px + env(safe-area-inset-top,0px)) 18px 16px;position:relative}
  #gdc .board::after{content:"";position:absolute;left:0;right:0;bottom:0;height:4px;background:linear-gradient(90deg,var(--red) 0 33%,transparent 33% 67%,var(--blue) 67%)}
  #gdc .top{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
  #gdc .top .brand{font:700 15px "Barlow Condensed",sans-serif;color:#AFC3DD}
  #gdc .close{background:transparent;color:#fff;border:1px solid #3A5578;border-radius:8px;padding:4px 10px;font:500 14px Barlow,sans-serif;min-height:34px}
  #gdc .date{font:500 15px "Barlow Condensed",sans-serif;color:#AFC3DD;margin:0 0 4px}
  #gdc .teams{display:grid;grid-template-columns:1fr auto 1fr;align-items:end;gap:8px}
  #gdc .team{font:700 26px/1.05 "Barlow Condensed",sans-serif;overflow-wrap:anywhere}
  #gdc .team.away{text-align:right}
  #gdc .v{font:500 15px "Barlow Condensed",sans-serif;color:#AFC3DD;padding-bottom:3px}
  #gdc .ph{color:#6F86A6}
  #gdc .venue{margin:6px 0 0;color:#AFC3DD;font-size:14px}
  #gdc .total{display:flex;justify-content:space-between;align-items:baseline;margin-top:12px;border-top:1px solid #2C4666;padding-top:8px}
  #gdc .total span{color:#AFC3DD;font-size:14px}
  #gdc .total b{font:700 32px/1 "Barlow Condensed",sans-serif;font-variant-numeric:tabular-nums}
  #gdc section{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px;margin:0 0 12px}
  #gdc section>h2{font-size:21px;font-weight:700}
  #gdc .sub{margin:0 0 12px;color:var(--muted);font-size:14px}
  #gdc details>summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:8px}
  #gdc details>summary::-webkit-details-marker{display:none}
  #gdc details>summary h2{font-size:21px}
  #gdc details>summary span{color:var(--muted);font-size:14px;text-align:right}
  #gdc details[open]>summary{margin-bottom:10px}
  #gdc .grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
  #gdc .full{grid-column:1/-1}
  #gdc label{display:block;font-size:14px;font-weight:600;margin:0 0 3px;color:var(--ink)}
  #gdc .hint{font-weight:400;color:var(--muted);font-size:13px}
  #gdc input,#gdc select,#gdc textarea{width:100%;font:16px Barlow,sans-serif;color:var(--ink);background:var(--ice);border:1px solid var(--line);border-radius:9px;padding:9px 10px;min-height:44px;margin:0;height:auto;box-sizing:border-box}
  #gdc textarea{resize:vertical;line-height:1.4}
  #gdc input[type=date],#gdc input[type=time]{-webkit-appearance:none;appearance:none;height:44px;min-height:44px;line-height:24px;text-align:left}
  #gdc input[type=date]::-webkit-date-and-time-value,#gdc input[type=time]::-webkit-date-and-time-value{text-align:left;margin:0;padding:0}
  #gdc input[type=date]::-webkit-datetime-edit,#gdc input[type=time]::-webkit-datetime-edit{padding:0;line-height:24px}
  #gdc input[type=checkbox]{width:22px;height:22px;min-height:0;accent-color:var(--blue)}
  #gdc input:focus-visible,#gdc select:focus-visible,#gdc button:focus-visible{outline:3px solid var(--blue);outline-offset:2px}
  #gdc .check{display:flex;gap:10px;align-items:center;font-weight:500}
  #gdc .route{font-size:13px;color:var(--muted);margin:4px 0 0}
  #gdc .route.good{color:var(--ok)}
  #gdc .route.bad{color:var(--red)}
  #gdc button{font:600 16px Barlow,sans-serif;border-radius:10px;border:0;padding:11px 14px;min-height:46px;cursor:pointer}
  #gdc .primary{background:var(--red);color:#fff;width:100%}
  #gdc .primary[disabled]{opacity:.55;cursor:default}
  #gdc .secondary{background:var(--crease);color:var(--ink)}
  #gdc .ghost{background:transparent;color:var(--blue);padding:6px 4px;min-height:34px}
  #gdc .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
  #gdc .extra{border:1px dashed var(--line);border-radius:10px;padding:10px;margin-bottom:10px;position:relative}
  #gdc .extra .rm{position:absolute;top:4px;right:6px}
  #gdc .photo{display:flex;align-items:center;gap:10px}
  #gdc .photo img{width:52px;height:52px;object-fit:cover;border-radius:8px;border:1px solid var(--line)}
  #gdc .plan{list-style:none;margin:0 0 12px;padding:0}
  #gdc .plan li{display:grid;grid-template-columns:26px 1fr auto;gap:8px;align-items:center;padding:9px 0;border-top:1px solid var(--line)}
  #gdc .plan li:first-child{border-top:0}
  #gdc .plan .mark{width:22px;height:22px;border-radius:50%;border:2px solid var(--line);display:grid;place-items:center;font-size:13px;font-weight:700}
  #gdc .plan li.doing .mark{border-color:var(--blue);border-top-color:transparent;animation:gdcspin .8s linear infinite}
  #gdc .plan li.done .mark{background:var(--ok);border-color:var(--ok);color:#fff}
  #gdc .plan li.fail .mark{background:var(--red);border-color:var(--red);color:#fff}
  #gdc .plan .what b{display:block;font-weight:600}
  #gdc .plan .what small{color:var(--muted);font-size:13px}
  #gdc .plan .amt{font:700 18px "Barlow Condensed",sans-serif;font-variant-numeric:tabular-nums}
  #gdc .msg{font-size:14px;margin:10px 0 0;min-height:1.3em}
  #gdc .msg.err{color:var(--red)}
  #gdc .msg.ok{color:var(--ok)}
  #gdc .note{font-size:13px;color:var(--muted);margin:10px 0 0}
  #gdc canvas{width:100%;height:110px;background:#fff;border:1px solid var(--line);border-radius:9px;touch-action:none;display:block}
  #gdc .sigrow{display:flex;justify-content:space-between;align-items:center;margin-top:4px}
  #gdc .testflag{background:#FFE08A;color:#4A3A00;font-size:13px;padding:6px 10px;border-radius:8px;margin:0 0 12px}
  @keyframes gdcspin{to{transform:rotate(360deg)}}
  @media (prefers-reduced-motion:reduce){#gdc .plan li.doing .mark{animation:none}}
  @media (max-width:400px){#gdc .grid{grid-template-columns:1fr}}`;
  const st=document.createElement("style"); st.textContent=css; document.head.appendChild(st);

  /* ---------- markup ---------- */
  const root=document.createElement("div"); root.id="gdc"; root.setAttribute("role","dialog"); root.setAttribute("aria-label","Game day claim");
  root.innerHTML = `
  <div class="wrap">
    <div class="board">
      <div class="top"><span class="brand">Game day claim</span><button type="button" class="close" data-x="close">Close</button></div>
      <p class="date" data-o="date">Pick a game date</p>
      <div class="teams"><div class="team" data-o="home"></div><div class="v">v</div><div class="team away" data-o="away"></div></div>
      <p class="venue" data-o="venue">&nbsp;</p>
      <div class="total"><span>Total to claim</span><b data-o="total">£0.00</b></div>
    </div>
    ${TEST?'<p class="testflag">Test mode: every draft description starts with "TEST - " so they are easy to delete.</p>':""}
    <section><details data-o="profileBox">
      <summary><h2>Your details</h2><span data-o="who">Fill in once</span></summary>
      <div class="grid">
        <div><label for="gdc-first">First name</label><input id="gdc-first" data-p="first" autocomplete="given-name"></div>
        <div><label for="gdc-last">Surname</label><input id="gdc-last" data-p="last" autocomplete="family-name"></div>
        <div><label for="gdc-town">Hometown</label><input id="gdc-town" data-p="town"></div>
        <div><label for="gdc-hpc">Home postcode</label><input id="gdc-hpc" data-p="homePc" autocapitalize="characters"></div>
        <div><label for="gdc-fee">Usual referee fee (£) <span class="hint">linesman defaults to £50</span></label><input id="gdc-fee" data-p="fee" type="number" inputmode="decimal" step="0.01"></div>
        <div><label for="gdc-comp">Usual competition</label><input id="gdc-comp" data-p="comp"></div>
        <div class="full"><label>Your signature <span class="hint">goes on the referee signature line</span></label>
          <canvas data-o="sig"></canvas>
          <div class="sigrow"><span class="hint" data-o="sigState">Sign with your finger</span><button type="button" class="ghost" data-x="sigClear">Clear</button></div></div>
      </div>
    </details></section>

    <section>
      <h2>The game</h2>
      <p class="sub">Fill this in once. The claim sheet and every ExpenseIn draft are made for you.</p>
      <div class="grid">
        <div><label for="gdc-date">Game date</label><input id="gdc-date" data-g="date" type="date"></div>
        <div><label for="gdc-arr">Time of arrival</label><input id="gdc-arr" data-g="arrive" type="time"></div>
        <div class="full"><label for="gdc-rink">Rink</label><select id="gdc-rink" data-g="rink"><option value="">Select a rink</option>${RINKS.map(r=>`<option value="${esc(r.key)}">${esc(r.key)} (${esc(r.venue)})</option>`).join("")}</select></div>
        <div class="full"><label for="gdc-rpc">Rink postcode</label><input id="gdc-rpc" data-g="rinkPc" autocapitalize="characters"></div>
        <div><label for="gdc-home">Home team</label><input id="gdc-home" data-g="home" list="gdc-teams"></div>
        <div><label for="gdc-away">Away team</label><input id="gdc-away" data-g="away" list="gdc-teams"></div>
        <div class="full"><label for="gdc-gcomp">Competition</label><input id="gdc-gcomp" data-g="comp"></div>
        <div><label for="gdc-position">Your role</label><select id="gdc-position" data-g="position"><option value="referee">Referee</option><option value="linesman">Linesman</option></select></div>
        <div><label for="gdc-gfee">Match fee (£) <span class="hint" data-o="feeHint">default £75</span></label><input id="gdc-gfee" data-g="fee" type="number" inputmode="decimal" step="0.01"></div>
        <div class="full" data-o="milesRow"><label for="gdc-miles">Miles there and back <span class="hint">worked out by ExpenseIn</span></label><input id="gdc-miles" data-g="miles" type="number" inputmode="decimal" step="0.1">
          <p class="route" data-o="route">Add your home postcode and the rink to work out the miles.</p></div>
        <div class="full"><label class="check"><input type="checkbox" data-g="shared"> Shared travel - I met another official on the way</label></div>
        <div class="full" data-o="sharedWrap" hidden>
          <label for="gdc-meetpc">Meeting point postcode <span class="hint">where you met - e.g. motorway services</span></label><input id="gdc-meetpc" data-g="meetPc" autocapitalize="characters">
          <label for="gdc-role" style="margin-top:10px">From the meeting point</label>
          <select id="gdc-role" data-g="role"><option value="passenger">Someone else drove - I rode with them</option><option value="driver">I drove - I carried the other official(s)</option></select>
          <div data-o="paxWrap" hidden><label for="gdc-pax" style="margin-top:10px">Passengers in your car</label><select id="gdc-pax" data-g="pax"><option value="1">1 passenger (0.50/mile)</option><option value="2">2 passengers (0.55/mile)</option></select></div>
          <p class="route" data-o="routeShared">Add your home and meeting point postcodes.</p></div>
        <div class="full" data-o="splitRow"><label class="check"><input type="checkbox" data-g="split"> Splitting travel across more than one game today</label></div>
        <div class="full" data-o="claimedWrap" hidden><label for="gdc-cl">Miles claimed against this game</label><input id="gdc-cl" data-g="claimed" type="number" inputmode="decimal" step="0.1"></div>
        <div class="full"><label for="gdc-mnotes">Travel notes <span class="hint">optional - e.g. who you shared with</span></label><textarea id="gdc-mnotes" data-g="mileNotes" rows="2"></textarea></div>
      </div>
      <datalist id="gdc-teams">${RINKS.map(r=>`<option value="${esc(r.key)}">`).join("")}</datalist>
    </section>

    <section>
      <h2>Extras</h2>
      <p class="sub">Parking, tolls, ULEZ or ferries. Snap the receipt and it's attached for you.</p>
      <div data-o="extras"></div>
      <div class="actions">
        <button type="button" class="secondary" data-add="park">Add parking</button>
        <button type="button" class="secondary" data-add="toll">Add toll or charge</button>
        <button type="button" class="secondary" data-add="ferry">Add ferry or flight</button>
      </div>
    </section>

    <section>
      <h2>Create your claim</h2>
      <p class="sub">These drafts will be added to ExpenseIn with the claim sheet and receipts attached.</p>
      <ul class="plan" data-o="plan"></ul>
      <button type="button" class="primary" data-x="go">Create drafts in ExpenseIn</button>
      <button type="button" class="secondary" data-x="save" style="margin-top:8px">Save a copy of my claim sheet</button>
      <p class="msg" data-o="msg" role="status"></p>
      <button type="button" class="primary" data-x="todrafts" data-o="toDrafts" hidden>Go to my drafts in ExpenseIn</button>
      <p class="note">Nothing is submitted. You'll see the drafts in ExpenseIn to check, then submit once for the week.</p>
    </section>
  </div>`;
  document.body.appendChild(root);
  const O = n => root.querySelector(`[data-o="${n}"]`);

  /* ---------- binding ---------- */
  root.querySelectorAll("[data-p]").forEach(el=>{ el.value=profile[el.dataset.p]||""; el.addEventListener("input",()=>{ profile[el.dataset.p]=el.value; store.set("profile",profile); if(el.dataset.p==="homePc") routeSoon();
    const gk={fee:"fee",comp:"comp"}[el.dataset.p]; if(gk){ const gi=root.querySelector(`[data-g="${gk}"]`); const applies = gk!=="fee" || game.position==="referee"; if(applies && !gi.dataset.touched){ game[gk]= gk==="fee"?feeFor("referee"):el.value; gi.value=game[gk]; } }
    render(); }); });
  if(!profile.first||!profile.homePc) O("profileBox").open=true;
  function loadGame(){ root.querySelectorAll("[data-g]").forEach(el=>{ const k=el.dataset.g; if(el.type==="checkbox") el.checked=!!game[k]; else el.value=game[k]||""; }); renderExtras(); }
  root.querySelectorAll("[data-g]").forEach(el=>el.addEventListener(el.tagName==="SELECT"||el.type==="checkbox"?"change":"input",()=>{
    const k=el.dataset.g; game[k]= el.type==="checkbox"?el.checked:el.value; el.dataset.touched="1";
    if(k==="rink"){ const r=RINKS.find(x=>x.key===game.rink); game.rinkPc = r?(pcs[r.key]||r.pc):""; root.querySelector('[data-g="rinkPc"]').value=game.rinkPc; if(r&&!game.home){ game.home=r.key; root.querySelector('[data-g="home"]').value=r.key; } route(); }
    if(k==="rinkPc"){ if(game.rink){ pcs[game.rink]=game.rinkPc.toUpperCase(); store.set("pc",pcs); } routeSoon(); }
    if(k==="miles") game.milesAuto=false;
    if(k==="split" && game.split && !game.claimed){ game.claimed = game.miles?String(Math.round(num(game.miles)/2*10)/10):""; root.querySelector('[data-g="claimed"]').value=game.claimed; }
    if(k==="position"){ const fe=root.querySelector('[data-g="fee"]'); if(!fe.dataset.touched){ game.fee=feeFor(game.position); fe.value=game.fee; } }
    if(k==="meetPc"){ game.meetPc=game.meetPc.toUpperCase(); el.value=game.meetPc; routeSoon(); }
    if(k==="shared"){ if(game.shared) game.split=false; route(); }
    if(k==="role") route();
    render();
  }));
  root.querySelector('[data-x="close"]').addEventListener("click",()=>{ root.hidden=true; });
  root.querySelector('[data-x="todrafts"]').addEventListener("click",()=>{ location.href="/"; });
  async function saveSheet(){
    const c=calc(), msg=O("msg");
    if(!profile.first||!profile.last){ O("profileBox").open=true; msg.className="msg err"; msg.textContent="Add your name under Your details first."; return; }
    if(!c.desc||!c.r){ msg.className="msg err"; msg.textContent="Add the game date, rink and both teams first."; return; }
    try{
      const blob=await buildPdf(c);
      const name=`IHUK claim ${game.date} ${game.home} v ${game.away}.pdf`.replace(/[\\/:*?"<>|]/g,"");
      const file=new File([blob],name,{type:"application/pdf"});
      if(navigator.canShare && navigator.canShare({files:[file]})){
        try{ await navigator.share({files:[file],title:name}); return; }
        catch(e){ if(e&&e.name==="AbortError") return; }
      }
      const url=URL.createObjectURL(blob); const a=document.createElement("a"); a.href=url; a.download=name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),4000);
      msg.className="msg ok"; msg.textContent="Saved a copy of your claim sheet.";
    }catch(e){ msg.className="msg err"; msg.textContent=(e&&e.message==="pdf")?"The claim sheet tool didn't load. Check your signal and try again.":"Couldn't make the copy. Try again."; }
  }
  root.querySelector('[data-x="save"]').addEventListener("click",saveSheet);
  loadPdfLib().catch(()=>{}); // warm up so Save a copy keeps its tap gesture on iOS
  root.querySelectorAll("[data-add]").forEach(b=>b.addEventListener("click",()=>{ const t=b.dataset.add; game.extras.push({type:t,desc:"",amount:"",vat:VAT[0]}); renderExtras(); render(); }));

  function renderExtras(){
    O("extras").innerHTML = game.extras.map((e,i)=>`
      <div class="extra">
        <button type="button" class="ghost rm" data-rm="${i}">Remove</button>
        <div class="grid">
          <div class="full"><span class="cond" style="font-size:17px;font-weight:700">${esc(EXTRA[e.type].label)}</span></div>
          <div class="full"><label for="gdc-xd${i}">What it was</label><input id="gdc-xd${i}" data-xi="${i}" data-xk="desc" value="${esc(e.desc)}" placeholder="${e.type==="park"?"Rink car park":e.type==="toll"?"Dartford Crossing":"Ferry"}"></div>
          <div><label for="gdc-xa${i}">Amount (£)</label><input id="gdc-xa${i}" data-xi="${i}" data-xk="amount" type="number" inputmode="decimal" step="0.01" value="${esc(e.amount)}"></div>
          <div><label for="gdc-xv${i}">VAT on receipt</label><select id="gdc-xv${i}" data-xi="${i}" data-xk="vat">${VAT.map(v=>`<option${v===e.vat?" selected":""}>${v}</option>`).join("")}</select></div>
          <div class="full"><label>Receipt</label><div class="photo">${files[i]?`<img alt="Receipt" src="${URL.createObjectURL(files[i])}">`:""}
            <label class="secondary" style="display:inline-block;padding:10px 14px;border-radius:10px;cursor:pointer;margin:0">${files[i]?"Change photo":"Take or choose photo"}<input type="file" accept="image/*,application/pdf" data-xf="${i}" hidden></label></div></div>
        </div>
      </div>`).join("");
    O("extras").querySelectorAll("[data-xk]").forEach(el=>el.addEventListener(el.tagName==="SELECT"?"change":"input",()=>{ game.extras[+el.dataset.xi][el.dataset.xk]=el.value; render(); }));
    O("extras").querySelectorAll("[data-xf]").forEach(el=>el.addEventListener("change",()=>{ if(el.files[0]){ files[+el.dataset.xf]=el.files[0]; renderExtras(); render(); } }));
    O("extras").querySelectorAll("[data-rm]").forEach(b=>b.addEventListener("click",()=>{ const i=+b.dataset.rm; game.extras.splice(i,1); for(let j=i;j<game.extras.length+1;j++) files[j]=files[j+1]; renderExtras(); render(); }));
  }

  /* ---------- ExpenseIn distance ---------- */
  let routeTimer=null;
  function routeSoon(){ clearTimeout(routeTimer); routeTimer=setTimeout(route,700); }
  async function leg(from,to){
    const r=await fetch(`/expenses/calculatemapdistance?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}&isReturn=true&_=${Date.now()}`,{credentials:"same-origin",headers:{"X-Requested-With":"XMLHttpRequest"}});
    const j=await r.json(); if(!j.DistanceCalculated) throw 0; return j;
  }
  async function route(){
    const home=(profile.homePc||"").trim(), rink=(game.rinkPc||"").trim();
    if(game.shared){
      const meet=(game.meetPc||"").trim(), el=O("routeShared");
      if(!home||!meet){ el.className="route"; el.textContent="Add your home and meeting point postcodes."; return; }
      el.className="route"; el.textContent="Working out the miles...";
      try{
        const d1=await leg(home,meet); game.soloMiles=String(d1.Distance);
        if(game.role==="driver"){
          if(!rink){ el.className="route"; el.textContent="Pick the rink too so I can work out the shared leg."; render(); return; }
          const d2=await leg(meet,rink); game.sharedMiles=String(d2.Distance);
          const pr=game.pax==="2"?"0.55":"0.50";
          el.className="route good"; el.innerHTML=`Your drive, solo: ${home.toUpperCase()} to ${meet.toUpperCase()} and back, ${d1.Distance} mi @ 0.45.<br>Your drive, carrying: ${meet.toUpperCase()} to ${rink.toUpperCase()} and back, ${d2.Distance} mi @ ${pr}.`;
        } else {
          game.sharedMiles="";
          el.className="route good"; el.innerHTML=`You claim your drive to the meeting point only: ${home.toUpperCase()} to ${meet.toUpperCase()} and back, ${d1.Distance} mi @ 0.45. The official who drove from there claims the rest.`;
        }
        render();
      }catch(e){ el.className="route bad"; el.textContent="ExpenseIn couldn't find that route. Check the postcodes."; }
      return;
    }
    const el=O("route");
    if(!home||!rink){ el.className="route"; el.textContent="Add your home postcode and the rink to work out the miles."; return; }
    el.className="route"; el.textContent="Working out the route...";
    try{
      const j=await leg(home,rink);
      game.miles=String(j.Distance); game.milesAuto=true; root.querySelector('[data-g="miles"]').value=game.miles;
      el.className="route good"; el.textContent=`${home.toUpperCase()} to ${rink.toUpperCase()} and back: ${j.Distance} miles, about ${Math.floor(j.Duration/3600000)}h ${Math.round(j.Duration/60000)%60}m driving.`;
      render();
    }catch(e){ el.className="route bad"; el.textContent="ExpenseIn couldn't find that route. Check the postcodes."; }
  }

  /* ---------- derived ---------- */
  function calc(){
    const r=RINKS.find(x=>x.key===game.rink), d=game.date?new Date(game.date+"T12:00:00"):null;
    const round2=n=>Math.round(n*100)/100;
    let legs=[], mileage=0, miles=0, claimed=0;
    if(game.shared){
      const solo=num(game.soloMiles);
      if(solo>0) legs.push({solo:true, from:(profile.homePc||"").toUpperCase().trim(), to:(game.meetPc||"").toUpperCase().trim(), miles:solo, rate:0.45, amt:round2(solo*0.45)});
      if(game.role==="driver"){
        const sh=num(game.sharedMiles), pr=game.pax==="2"?0.55:0.50;
        if(sh>0) legs.push({solo:false, pax:game.pax, from:(game.meetPc||"").toUpperCase().trim(), to:(game.rinkPc||"").toUpperCase().trim(), miles:sh, rate:pr, amt:round2(sh*pr)});
      }
      mileage=legs.reduce((s,l)=>s+l.amt,0); miles=legs.reduce((s,l)=>s+l.miles,0);
    } else {
      miles=num(game.miles); claimed=game.split?num(game.claimed):miles; mileage=round2(claimed*RATE);
      if(claimed>0) legs.push({solo:true, single:true, from:(profile.homePc||"").toUpperCase().trim(), to:(game.rinkPc||"").toUpperCase().trim(), miles:claimed, rate:RATE, amt:mileage});
    }
    const extras=game.extras.map((e,i)=>({...e,i})).filter(e=>num(e.amount)>0);
    const extrasTotal=extras.reduce((s,e)=>s+num(e.amount),0);
    const fee=num(game.fee), travel=mileage+extrasTotal;
    const desc=(d&&game.home&&game.away)?`${TEST?"TEST - ":""}${String(d.getDate()).padStart(2,"0")} ${MONTHS[d.getMonth()]} ${d.getFullYear()} - ${game.home.trim()} v ${game.away.trim()}`:"";
    return {r,d,miles,claimed,mileage,legs,extras,extrasTotal,fee,travel,total:travel+fee,desc,
      uk:d?d.toLocaleDateString("en-GB"):"", long:d?d.toLocaleDateString("en-GB",{weekday:"long",day:"numeric",month:"long",year:"numeric"}):""};
  }
  function lines(c){
    const L=[{kind:"fee",title:"Match fee"+(game.position==="linesman"?" (linesman)":""),sub:"with claim sheet",amt:c.fee}];
    c.legs.forEach(l=>{
      const title = c.legs.length>1 ? (l.solo?"Mileage (solo leg)":"Mileage (with passenger"+(l.pax==="2"?"s":"")+")") : "Mileage";
      L.push({kind:"mileage",leg:l,title,sub:`${l.miles} miles at £${l.rate.toFixed(2)}, with claim sheet`,amt:l.amt});
    });
    c.extras.forEach(e=>L.push({kind:"extra",e,title:EXTRA[e.type].label,sub:files[e.i]?"with receipt photo":"receipt photo needed",amt:num(e.amount)}));
    return L;
  }
  function render(){
    const c=calc();
    O("date").textContent=c.long||"Pick a game date";
    O("home").innerHTML=game.home?esc(game.home):'<span class="ph">Home</span>';
    O("away").innerHTML=game.away?esc(game.away):'<span class="ph">Away</span>';
    O("venue").textContent=c.r?c.r.venue:"\u00a0";
    O("total").textContent="£"+money(c.total);
    O("who").textContent=(profile.first||profile.last)?`${profile.first} ${profile.last}`.trim():"Fill in once";
    O("feeHint").textContent="default £"+feeFor(game.position);
    O("sharedWrap").hidden=!game.shared;
    O("paxWrap").hidden=!(game.shared&&game.role==="driver");
    O("milesRow").hidden=game.shared;
    O("splitRow").hidden=game.shared;
    O("claimedWrap").hidden=!game.split||game.shared;
    if(!running) O("plan").innerHTML = lines(c).map((l,i)=>`<li data-l="${i}"><span class="mark"></span><span class="what"><b>${esc(l.title)}</b><small>${esc(l.sub)}</small></span><span class="amt">£${money(l.amt)}</span></li>`).join("");
  }

  /* ---------- signature ---------- */
  (function(){
    const cv=O("sig"), ctx=cv.getContext("2d"); let on=false, dirty=false, sized=false;
    function size(){ const r=cv.getBoundingClientRect(); if(!r.width||!r.height) return; const dpr=window.devicePixelRatio||1; const w=Math.round(r.width*dpr), h=Math.round(r.height*dpr); if(cv.width===w && cv.height===h && sized) return; const prev=profile.sig; cv.width=w; cv.height=h; ctx.setTransform(1,0,0,1,0,0); ctx.lineWidth=2.2*dpr; ctx.lineCap="round"; ctx.lineJoin="round"; ctx.strokeStyle="#0D1A5A"; sized=true; if(prev){ const im=new Image(); im.onload=()=>ctx.drawImage(im,0,0,cv.width,cv.height); im.src=prev; } }
    // map a pointer event to backing-store pixels, correct across the whole pad regardless of CSS size or when sizing ran
    const pt=e=>{ const r=cv.getBoundingClientRect(); return [ (e.clientX-r.left)*(cv.width/r.width), (e.clientY-r.top)*(cv.height/r.height) ]; };
    cv.addEventListener("pointerdown",e=>{ e.preventDefault(); size(); on=true; try{cv.setPointerCapture(e.pointerId);}catch(_){ } ctx.beginPath(); ctx.moveTo(...pt(e)); });
    cv.addEventListener("pointermove",e=>{ if(!on) return; e.preventDefault(); ctx.lineTo(...pt(e)); ctx.stroke(); dirty=true; });
    const end=()=>{ if(!on) return; on=false; if(dirty){ profile.sig=cv.toDataURL("image/png"); store.set("profile",profile); O("sigState").textContent="Signature saved"; } };
    cv.addEventListener("pointerup",end); cv.addEventListener("pointercancel",end); cv.addEventListener("pointerleave",end);
    root.querySelector('[data-x="sigClear"]').addEventListener("click",()=>{ ctx.setTransform(1,0,0,1,0,0); ctx.clearRect(0,0,cv.width,cv.height); profile.sig=""; dirty=false; store.set("profile",profile); O("sigState").textContent="Sign with your finger"; });
    O("profileBox").addEventListener("toggle",()=>{ if(O("profileBox").open) requestAnimationFrame(()=>{ sized=false; size(); }); });
    if(window.ResizeObserver){ const ro=new ResizeObserver(()=>{ sized=false; size(); }); ro.observe(cv); }
    window.addEventListener("orientationchange",()=>{ sized=false; requestAnimationFrame(size); });
    if(profile.sig) O("sigState").textContent="Signature saved";
    requestAnimationFrame(size);
  })();

  /* ---------- claim sheet PDF ---------- */
  function loadPdfLib(){
    if(window.PDFLib) return Promise.resolve();
    return new Promise((ok,bad)=>{ const s=document.createElement("script"); s.src="https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js"; s.onload=ok; s.onerror=()=>bad(new Error("pdf")); document.head.appendChild(s); });
  }
  async function buildPdf(c){
    await loadPdfLib();
    const {PDFDocument,StandardFonts,rgb}=PDFLib;
    if(!HAS_FORM) return demoSheet(c);
    const pdf=await PDFDocument.load(Uint8Array.from(atob(FORM_B64),ch=>ch.charCodeAt(0)));
    const page=pdf.getPages()[0], H=page.getHeight(), font=await pdf.embedFont(StandardFonts.HelveticaBold), ink=rgb(0.05,0.1,0.4);
    const put=(t,x0,top,x1,bot,size=10)=>{ if(t===""||t==null) return; t=String(t).toUpperCase(); let s=size; while(font.widthOfTextAtSize(t,s)>x1-x0-8&&s>5) s-=0.5; page.drawText(t,{x:x0+4,y:H-(top+bot)/2-s*0.35,size:s,font,color:ink}); };
    const ring=(x0,x1,cy)=>page.drawEllipse({x:(x0+x1)/2,y:H-cy,xScale:(x1-x0)/2+2.5,yScale:6,borderColor:ink,borderWidth:1.2});
    put(profile.first,110,98,272,124); put(profile.last,344,98,492,124); put(c.uk,677,98,802,124);
    put(profile.town,110,125,272,152); put(c.r?c.r.venue:"",344,125,492,152); put(game.arrive,677,125,802,152);
    const totMiles=game.shared?(num(game.soloMiles)+num(game.sharedMiles)):c.miles;
    if(totMiles>0) put(String(Math.round(totMiles*10)/10),195,186,279,215);
    game.split?ring(743,759,198):ring(725,737,198);
    if(c.mileage>0){ put(String(Math.round((game.shared?totMiles:c.claimed)*10)/10),301,226,407,255); put(money(c.mileage),695,226,802,255); }
    // shared-travel breakdown in the white band between the mileage row and the car-park row
    if(game.shared){
      const mp=(game.meetPc||"").toUpperCase().trim();
      let note;
      if(c.legs.length>1){ const s=c.legs[0], p=c.legs[1]; note=`SHARED TRAVEL VIA ${mp}:  ${s.miles} MI @ £${s.rate.toFixed(2)}  +  ${p.miles} MI @ £${p.rate.toFixed(2)} (CARRYING ${p.pax==="2"?"2":"1"})`; }
      else { note=`DROVE TO MEETING POINT ${mp} ONLY (${totMiles} MI); RODE WITH ANOTHER OFFICIAL TO THE RINK`; }
      let sz=7; while(font.widthOfTextAtSize(note,sz)>756 && sz>5) sz-=0.25;
      page.drawText(note,{x:44,y:H-262,size:sz,font,color:ink});
    }
    [["park",266,289,278.5],["toll",289,312,301],["ferry",312,334,324]].forEach(([t,top,bot,cy])=>{
      const it=c.extras.filter(e=>e.type===t);
      it.length?ring(202,218,cy):ring(188,199,cy);
      if(it.length){ put(it.map(e=>e.desc||EXTRA[t].merchant).join(", "),408,top,675,bot,9); put(money(it.reduce((s,e)=>s+num(e.amount),0)),695,top,802,bot); }
    });
    put(money(c.travel),695,334,802,358);
    put(game.comp,38,380,176,402,9); put(game.home,177,380,406,402); put(game.away,407,380,675,402); put(money(c.fee),695,380,802,402);
    put(money(c.total),695,413,802,435);
    if(profile.sig){ try{ const png=await pdf.embedPng(profile.sig); const h=26,w=Math.min(png.width*h/png.height,220); page.drawImage(png,{x:130,y:H-487,width:w,height:h}); }catch(e){} }
    return new Blob([await pdf.save()],{type:"application/pdf"});
  }


  async function demoSheet(c){
    const {PDFDocument,StandardFonts,rgb}=PDFLib;
    const pdf=await PDFDocument.create(); const page=pdf.addPage([842,595]);
    const b=await pdf.embedFont(StandardFonts.HelveticaBold), r=await pdf.embedFont(StandardFonts.Helvetica);
    page.drawText("DEMO CLAIM SHEET - the live version fills the real IHUK form",{x:40,y:545,size:16,font:b,color:rgb(0.78,0.06,0.18)});
    const rows=[["Referee",`${profile.first} ${profile.last}`],["Hometown",profile.town],["Date",c.uk],["Rink",c.r.venue],["Arrival",game.arrive],
      ["Game",`${game.home} v ${game.away} (${game.comp})`],["Miles",`${c.claimed} @ 0.45 = ${money(c.mileage)}`],
      ...c.extras.map(e=>[EXTRA[e.type].label,`${e.desc||""} ${money(e.amount)}`]),["Travel total",money(c.travel)],["Match fee",money(c.fee)],["Total invoiced",money(c.total)]];
    rows.forEach(([k,v],i)=>{ page.drawText(k.toUpperCase(),{x:40,y:500-i*26,size:11,font:b}); page.drawText(String(v||"").toUpperCase(),{x:220,y:500-i*26,size:11,font:r,color:rgb(0.05,0.1,0.4)}); });
    return new Blob([await pdf.save()],{type:"application/pdf"});
  }
  /* ---------- ExpenseIn calls ---------- */
  const XH={"X-Requested-With":"XMLHttpRequest"};
  async function formMeta(path){
    const html=await (await fetch(path,{credentials:"same-origin"})).text();
    const f=new DOMParser().parseFromString(html,"text/html").forms[0];
    if(!f) throw new Error("ExpenseIn didn't return the expense form. Are you still signed in?");
    const hidden={}; f.querySelectorAll('input[type=hidden]').forEach(i=>{ if(i.name && i.name!=="IsReturn" && !/^Receipts/.test(i.name)) hidden[i.name]=i.value; });
    const opt=(id,test)=>{ const s=f.querySelector("#"+id); const o=s&&[...s.options].find(o=>test(o.text.trim())); if(!o) throw new Error(`Couldn't find the "${id}" option in ExpenseIn.`); return o.value; };
    return {hidden,opt};
  }
  async function upload(blob,name){
    const fd=new FormData(); fd.append("file",blob,name);
    const r=await fetch("/expenses/savetempreceipt",{method:"POST",body:fd,credentials:"same-origin",headers:XH});
    const j=await r.json().catch(()=>null);
    if(!j||!j.Success||!j.Data) throw new Error(`Uploading ${name} failed.`);
    return [["Receipts[0].TempReceiptName",j.Data.TempFileName],["Receipts[0].OriginalFileName",j.Data.OriginalFileName]];
  }
  async function create(path,pairs){
    const body=new URLSearchParams(); pairs.forEach(([k,v])=>body.append(k,v??""));
    const r=await fetch(path,{method:"POST",body,credentials:"same-origin",headers:{...XH,"Content-Type":"application/x-www-form-urlencoded; charset=UTF-8"}});
    const j=await r.json().catch(()=>null);
    if(!j||!j.Success){ const v=j&&j.ValidationErrors; throw new Error(v?Object.values(v).flat().join(" "):(j&&j.Message)||"ExpenseIn didn't accept this line."); }
  }

  let running=false;
  root.querySelector('[data-x="go"]').addEventListener("click",async()=>{
    const c=calc(), msg=O("msg"), btn=root.querySelector('[data-x="go"]');
    const fail=t=>{ msg.className="msg err"; msg.textContent=t; };
    if(!profile.first||!profile.last||!profile.homePc){ O("profileBox").open=true; return fail("Add your name and home postcode under Your details."); }
    if(!c.desc||!c.r) return fail("Add the game date, rink and both teams.");
    if(!game.rinkPc) return fail("Add the rink postcode.");
    if(c.fee<=0) return fail("Add the match fee.");
    const missing=c.extras.find(e=>!files[e.i]); if(missing) return fail(`Add a receipt photo for the ${EXTRA[missing.type].label.toLowerCase()}. ExpenseIn needs one for every purchase.`);
    const done=store.get("done",[]), key=`${game.date}|${game.home}|${game.away}`.toLowerCase();
    if(done.includes(key) && !confirm("You've already created drafts for this game. Create them again?")) return;

    running=true; btn.disabled=true; msg.className="msg"; msg.textContent="Making your claim sheet...";
    const L=lines(c), li=i=>O("plan").querySelector(`[data-l="${i}"]`);
    const setState=(i,s)=>{ const el=li(i); el.className=s; el.querySelector(".mark").textContent=s==="done"?"✓":s==="fail"?"!":""; };
    try{
      const sheet=await buildPdf(c);
      const sheetName=`IHUK claim ${game.date} ${game.home} v ${game.away}.pdf`.replace(/[\\/:*?"<>|]/g,"");
      const P=await formMeta("/expenses/newpurchase");
      const cat=P.opt("CategoryId",t=>t==="Fees - Referees Expenses");
      const ev=P.opt("ProjectId",t=>t.toLowerCase()===("referee - "+c.r.key).toLowerCase());
      const vatId=t=>P.opt("TaxRateId",x=>x===t);
      const base=[["ExpenseDate",game.date],["Description",c.desc],["CategoryId",cat],["NumberOfNights",""],["ProjectId",ev]];
      const hid=h=>Object.entries(h);
      for(let i=0;i<L.length;i++){
        const l=L[i]; setState(i,"doing"); msg.textContent=`Creating ${l.title.toLowerCase()}...`;
        if(l.kind==="fee"){
          const rc=await upload(sheet,sheetName);
          await create("/expenses/newpurchase",[["UserId",P.hidden.UserId],...rc,...base,["CurrencyId",P.hidden.CurrencyId],["ExchangeRate",P.hidden.ExchangeRate],["PurchaseMethodId",P.hidden.PurchaseMethodId],["MerchantName",game.position==="linesman"?"Linesman":"Referee"],["Amount",money(c.fee)],["TaxRateId",vatId("Zero Rated (0%)")],["Notes",""]]);
        } else if(l.kind==="mileage"){
          const M=await formMeta("/expenses/newmileage");
          const rc=await upload(sheet,sheetName);
          const lg=l.leg, rateRe = lg.rate>=0.55?/2 passengers.*\(0\.55\)/i : lg.rate>=0.50?/1 passenger.*\(0\.50\)/i : /under 10k miles \(0\.45\)/i;
          await create("/expenses/newmileage",[["UserId",M.hidden.UserId],...rc,...base,["From",lg.from],["To[0]",lg.to],["IsReturn","true"],["IsReturn","false"],["DistanceUnit",M.hidden.DistanceUnit||"Miles"],["Distance",String(lg.miles)],["MileageRateId",M.opt("MileageRateId",t=>rateRe.test(t))],["VehicleSpecificationId",M.opt("VehicleSpecificationId",t=>/^Any/.test(t))],["Notes",game.mileNotes||""]]);
        } else {
          const f=files[l.e.i];
          const rc=await upload(f,f.name||"receipt.jpg");
          await create("/expenses/newpurchase",[["UserId",P.hidden.UserId],...rc,...base,["CurrencyId",P.hidden.CurrencyId],["ExchangeRate",P.hidden.ExchangeRate],["PurchaseMethodId",P.hidden.PurchaseMethodId],["MerchantName",EXTRA[l.e.type].merchant],["Amount",money(l.e.amount)],["TaxRateId",vatId(l.e.vat)],["Notes",l.e.desc||""]]);
        }
        setState(i,"done");
      }
      done.push(key); store.set("done",done.slice(-100));
      msg.className="msg ok"; msg.textContent=`All ${L.length} drafts created. Tap "Save a copy" if you'd like a record, then go to your drafts to check and submit.`;
      O("toDrafts").hidden=false; btn.disabled=false; running=false;
    }catch(e){
      const i=[...O("plan").children].findIndex(x=>x.className==="doing"); if(i>=0) setState(i,"fail");
      fail((e&&e.message==="pdf")?"The claim sheet tool didn't load. Check your signal and try again.":(e&&e.message)||"Something went wrong. Check your drafts before trying again.");
      running=false; btn.disabled=false;
    }
  });

  loadGame(); render(); route();
})();
